SELECT 1 FROM zasp_ordered_public62.registration WHERE checksum='e4dfae0a990718c2c6b7518b07d7c146cfb9025656378d423c8d96188bcf1b96' AND fingerprint='07e774a28105095c73275ad959c765a3fddda9ee9aa81e81cd3828222e40aad3')\n  OR (SELECT count(*) FROM zasp_temporal65.registration)<>1 OR NOT EXISTS(SELECT 1 FROM zasp_temporal65.registration x JOIN zasp_temporal67.registration y ON x.predecessor=y.outbox_predecessor WHERE x.checksum='2cb65040d3be0f7a08722691c5c1fe38b93b4d036cec6b74b4b2ec83c3a2d56a' AND x.fingerprint='8c64101128b0b31cd4d12575480035ab1e30f157d92fa96c236babc7620de3f8')\n  OR (SELECT count(*) FROM zasp_temporal66.registration)<>1 OR NOT EXISTS(SELECT 1 FROM zasp_temporal66.registration WHERE checksum='6e2fbdef64421286476be12a02188d7936e81db3126764bf2ab55e099fcb12cb' AND fingerprint='422b211febdd6e2b37882dc3f5961a79ca5c58f3f87f1642f7babf1224fbe94a')","suffix":" THEN RETURN false;END IF;\n FOREACH n IN ARRAY ARRAY['zasp_ordered_worker63','zasp_ordered_scheduler64'] LOOP\n  SELECT * INTO retired FROM zasp_temporal66.retired_authorities WHERE schema_name=n;\n  IF (to_regnamespace(n) IS NOT NULL) IS DISTINCT FROM FOUND THEN RETURN false;END IF;\n  IF NOT FOUND THEN CONTINUE;END IF;\n  IF retired.original_fingerprint IS DISTINCT FROM (CASE n WHEN 'zasp_ordered_worker63' THEN 'c81c4cb4cb799894ab9bf69b16815341ac53665e967fd0405b32009898510239' ELSE '9a8a090c97a4c8b913921dd1503b6ca0925c837adf5da9219c3c8f1e3a6d0419' END) THEN RETURN false;END IF;\n  EXECUTE format('SELECT %I.fingerprint()',n) INTO actual;\n  IF actual IS DISTINCT FROM retired.retired_fingerprint OR EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace=to_regnamespace(n) AND has_function_privilege('zasp_security_agent_worker',oid,'EXECUTE')) THEN RETURN false;END IF;\n END LOOP;\n RETURN true;\nEND ","query":"SELECT CASE WHEN current_user='zasp_discovery_authority' THEN (WITH higher_catalog(value) AS MATERIALIZED (SELECT CASE WHEN EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid='zasp_authorization80_worker.catalog_ready()'::regprocedure AND p.proowner='zasp_discovery_authority'::regrole AND p.proacl::text='{zasp_discovery_authority=X/zasp_discovery_authority}' AND encode(digest(convert_to(replace(replace(pg_get_functiondef(p.oid),'-- worker profile checksum','<worker-checksum>'),'-- worker catalog body digest','<worker-catalog>'),'UTF8'),'sha256'),'hex')='3b46aa8607e042925c3cc56b66605244a0a6fe9ff2db41fcd339c8e6c7bebac8') AND EXISTS(SELECT 1 FROM zasp_authorization80_worker.registration WHERE checksum='-- worker profile checksum') THEN zasp_authorization80_worker.catalog_ready() ELSE NULL END) SELECT CASE WHEN (SELECT value FROM higher_catalog) THEN (WITH higher_0(value) AS MATERIALIZED (SELECT CASE WHEN EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid='zasp_authorization80_worker.catalog_ready()'::regprocedure AND encode(digest(convert_to(p.prosrc,'UTF8'),'sha256'),'hex')='-- worker catalog body digest' AND p.proowner='zasp_discovery_authority'::regrole AND p.prosecdef AND p.provolatile='s' AND l.lanname='sql' AND p.proconfig=ARRAY['search_path=pg_catalog, public'] AND p.proacl::text='{zasp_discovery_authority=X/zasp_discovery_authority}') AND EXISTS(SELECT 1 FROM zasp_authorization80_worker.registration WHERE checksum='-- worker profile checksum') AND (SELECT value FROM higher_catalog) THEN zasp_authorization80_worker.projected78() ELSE NULL END),higher_1(value) AS MATERIALIZED (SELECT COALESCE((SELECT count(*)=1 FROM zasp_temporal78.registration) AND EXISTS(SELECT 1 FROM zasp_temporal78.registration WHERE checksum='29f2a16ea6d9021f159196106a9a57547cca797beaf87cc1fe15a937ae9b6021' AND fingerprint='11b999b767465c01389f4482f9196852905866873e585574888281220538d1d4') AND (SELECT value FROM higher_0)='11b999b767465c01389f4482f9196852905866873e585574888281220538d1d4',false)),higher_2(value) AS MATERIALIZED (SELECT CASE WHEN (SELECT value FROM higher_1) THEN zasp_temporal78.predecessor77_fingerprint() ELSE NULL END),higher_3(value) AS MATERIALIZED (SELECT COALESCE((SELECT count(*)=1 FROM zasp_temporal77.registration) AND EXISTS(SELECT 1 FROM zasp_temporal77.registration WHERE checksum='3b6117ba1b9b0e9cc2871bc89bf0027b7ca3d400b1354f0550c068f2145de3fb' AND fingerprint='8cac13406a1886a98cd327065e5525be28997add7a9bd359d12e7b4ed219f5ef') AND (SELECT value FROM higher_2)='8cac13406a1886a98cd327065e5525be28997add7a9bd359d12e7b4ed219f5ef',false)),higher_4(value) AS MATERIALIZED (SELECT CASE WHEN EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid='zasp_authorization80_worker.catalog_ready()'::regprocedure AND encode(digest(convert_to(p.prosrc,'UTF8'),'sha256'),'hex')='-- worker catalog body digest' AND p.proowner='zasp_discovery_authority'::regrole AND p.prosecdef AND p.provolatile='s' AND l.lanname='sql' AND p.proconfig=ARRAY['search_path=pg_catalog, public'] AND p.proacl::text='{zasp_discovery_authority=X/zasp_discovery_authority}') AND EXISTS(SELECT 1 FROM zasp_authorization80_worker.registration WHERE checksum='-- worker profile checksum') AND (SELECT value FROM higher_catalog) THEN zasp_authorization80_worker.projected_temporal_profile() ELSE NULL END),higher_5(value) AS MATERIALIZED (SELECT CASE WHEN EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid='zasp_authorization80_worker.catalog_ready()'::regprocedure AND encode(digest(convert_to(p.prosrc,'UTF8'),'sha256'),'hex')='-- worker catalog body digest' AND p.proowner='zasp_discovery_authority'::regrole AND p.prosecdef AND p.provolatile='s' AND l.lanname='sql' AND p.proconfig=ARRAY['search_path=pg_catalog, public'] AND p.proacl::text='{zasp_discovery_authority=X/zasp_discovery_authority}') AND EXISTS(SELECT 1 FROM zasp_authorization80_worker.registration WHERE checksum='-- worker profile checksum') AND (SELECT value FROM higher_catalog) THEN zasp_authorization80_worker.projected79() ELSE NULL END),higher_6(value) AS MATERIALIZED (SELECT CASE WHEN EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prol