ame":"value","type":"oid"},"cte":null,"edits":[{"target":"zasp_temporal72.fingerprint()","targets":["zasp_temporal72.fingerprint()"],"start":414,"end":443,"args":"","text":"zasp_temporal72.fingerprint()"}]},{"signature":"zasp_discovery_schedule_replay_live_fingerprint()","sourceHash":"8ed5df9ba2dc68a3f03b50c6a7087425673789290b2b857cc30be19bcdfeea51","definitionHash":"436b3586e2d2e2238c82520b3b238ebc89df78d3b3de79d3e7e5e4568aab5231","sourceLength":2634,"securityDefiner":false,"acl":"{zasp_discovery_authority=X/zasp_discovery_authority}","opaqueDescendant":true,"parameter":null,"cte":"readiness_11","edits":[{"target":"zasp_discovery_schedule_replay_function_identity(oid)","targets":["zasp_discovery_schedule_replay_function_identity(oid)"],"start":736,"end":798,"args":"p.oid","text":"public.zasp_discovery_schedule_replay_function_identity(p.oid)"},{"target":"zasp_execution_live_fingerprint()","targets":["zasp_execution_live_fingerprint()"],"start":149,"end":189,"args":"","text":"public.zasp_execution_live_fingerprint()"},{"target":"zasp_sa_webhook_live_fingerprint()","targets":["zasp_sa_webhook_live_fingerprint()"],"start":62,"end":103,"args":"","text":"public.zasp_sa_webhook_live_fingerprint()"}]},{"signature":"zasp_temporal77.base67_fingerprint()","sourceHash":"604cb02288a00024e6816728fdf954988a2224cd1a7e31fc601294fb2503acd8","definitionHash":"1c00ffffdf90307f3b99bc9eae0645df72442cebc58f34df6a873536cf1a6e92","sourceLength":6902,"securityDefiner":false,"acl":"{zasp_discovery_authority=X/zasp_discovery_authority}","opaqueDescendant":true,"parameter":null,"cte":null,"edits":[{"target":"zasp_discovery_schedule_replay_live_fingerprint()","targets":["zasp_discovery_schedule_replay_live_fingerprint()"],"start":155,"end":211,"args":"","text":"public.zasp_discovery_schedule_replay_live_fingerprint()"}]}]$readiness_records$::jsonb;
 p jsonb;e jsonb;f record;source_value text;original_value text;replacement text;computed jsonb:='{}';ctes text:='';query_value text;definition_value text;start_value integer;end_value integer;catalog_cte text;
BEGIN
 FOR p IN SELECT value FROM jsonb_array_elements(records) LOOP
  SELECT pg_get_functiondef(x.oid) definition,x.prosrc,x.proowner::regrole::text owner_name,x.proacl::text acl,l.lanname,x.provolatile,x.proisstrict,x.proparallel,x.prosecdef,x.proconfig INTO STRICT f FROM pg_proc x JOIN pg_language l ON l.oid=x.prolang WHERE x.oid=(p->>'signature')::regprocedure;
  IF f.owner_name<>'zasp_discovery_authority' OR f.acl IS DISTINCT FROM p->>'acl' OR f.lanname<>'sql' OR f.provolatile<>'s' OR f.proisstrict OR f.proparallel<>'u' OR f.prosecdef IS DISTINCT FROM(p->>'securityDefiner')::boolean OR f.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, public']
   OR length(f.prosrc)<>(p->>'sourceLength')::integer OR encode(digest(convert_to(replace(replace(f.prosrc,'-- worker profile checksum','<worker-checksum>'),'-- worker catalog body digest','<worker-catalog>'),'UTF8'),'sha256'),'hex')<>p->>'sourceHash'
   OR encode(digest(convert_to(replace(replace(f.definition,'-- worker profile checksum','<worker-checksum>'),'-- worker catalog body digest','<worker-catalog>'),'UTF8'),'sha256'),'hex')<>p->>'definitionHash'
  THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='readiness graph exact source or frame changed';END IF;
  IF p->>'signature'<>'zasp_authorization80_worker.catalog_ready()' AND split_part(p->>'signature','.',1)<>'zasp_authorization80_worker' THEN
   INSERT INTO zasp_authorization80_worker.predecessor_functions SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc WHERE oid=(p->>'signature')::regprocedure ON CONFLICT(signature) DO NOTHING;
  END IF;
  source_value:=f.prosrc;
  IF p->>'signature'='zasp_temporal77.base67_fingerprint()' THEN original_value:=source_value;END IF;
  FOR e IN SELECT value FROM jsonb_array_elements(p->'edits') LOOP
   start_value:=(e->>'start')::integer;end_value:=(e->>'end')::integer;
   IF substring(source_value FROM start_value+1 FOR end_value-start_value) IS DISTINCT FROM e->>'text' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='readiness graph call anchor changed';END IF;
   SELECT value INTO STRICT query_value FROM jsonb_each_text(computed) WHERE key=e->>'target';
   replacement:=replace(query_value,'<readiness-argument>',e->>'args');
   source_value:=substring(source_value FROM 1 FOR start_value)||replacement||substring(source_value FROM end_value+1);
  END LOOP;
  source_value:=regexp_replace(btrim(source_value),';[[:space:]]*$','');
  IF p->'parameter'<>'null'::jsonb THEN
   computed:=computed||jsonb_build_object(p->>'signature','('||source_value||' FROM (SELECT (<readiness-argument>)::'||(p#>>'{parameter,type}')||' AS '||quote_ident(p#>>'{parameter,name}')||') AS readiness_argument)');
  ELSIF p->>'signature'<>'zasp_temporal77.base67_fingerprint()' AND (p->>'opaqueDescendant')::boolean THEN
   computed:=computed||jsonb_build_object(p->>'signature','('||source_value||')');
  ELSIF p->>'signature'<>'zasp_temporal77.base67_fingerprint()' THEN
   IF ctes<>'' THEN ctes:=ctes||',';END IF;
   ctes:=ctes||quote_ident(p->>'cte')||'(value) AS MATERIALIZED ('||CASE WHEN p->>'signature'='zasp_authorization80_worker.catalog_ready()' THEN 'SELECT zasp_authorization80_worker.catalog_ready()' ELSE source_value END||')';
   computed:=computed||jsonb_build_object(p->>'signature','(SELECT value FROM '||quote_ident(p->>'cte')||')');
  ELSE
   catalog_cte:='readiness_0(value) AS MATERIALIZED (SELECT zasp_authorization80_worker.catalog_ready())';
   IF left(ctes,length(catalog_cte)+1)<>catalog_cte||',' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='readiness graph materialized gate changed';END IF;
   query_value:='SELECT CASE WHEN current_user=''zasp_discovery_authority'' THEN (WITH '||catalog_cte||' SELECT CASE WHEN (SELECT value FROM readiness_0) THEN (WITH '||substring(ctes FROM length(catalog_cte)+2)||' SELECT ('||source_value||')) ELSE ('||regexp_replace(btrim(original_value),';[[:space:]]*$','')||') END) ELSE ('||regexp_replace(btrim(original_value),';[[:space:]]*$','')||') END';
  END IF;
 END LOOP;
 definition_value:=pg_get_functiondef('zasp_temporal77.base67_fingerprint()'::regprocedure);
 IF (length(definition_value)-length(replace(definition_value,original_value,'')))/length(original_value)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='readiness graph root body anchor changed';END IF;
 EXECUTE replace(definition_value,original_value,E'\n'||query_value||E'\n');
END $readiness_graph$;
